import { useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function LoginSuccess() {
  const navigate = useNavigate();

  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get("token");

    if (!token) {
      alert("Invalid login link");
      return;
    }

    axios
      .get(`http://localhost:3597/api/user/verify?token=${token}`)
      .then((res) => {
        localStorage.setItem("authToken", res.data.token);
        alert("Login successful");
        navigate("/dashboard");
      })
      .catch(() => {
        alert("Link expired or invalid");
      });
  }, [navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center" style={{ background: 'linear-gradient(135deg, #0a0f1e 0%, #1a1f35 100%)' }}>
      <div className="text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-indigo-500/20 flex items-center justify-center animate-pulse-glow">
          <div className="w-10 h-10 border-4 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
        </div>
        <h2 className="text-2xl font-semibold text-white mb-2">Logging you in...</h2>
        <p className="text-gray-400">Please wait while we verify your magic link</p>
      </div>
    </div>
  );
}
